import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Prisma indefinito","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/g_geometria-dello-spazio/gi/gia.md","filePath":"lezioni/g_geometria-dello-spazio/gi/gia.md"}`),a={name:`lezioni/g_geometria-dello-spazio/gi/gia.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="prisma-indefinito" tabindex="-1">Prisma indefinito <a class="header-anchor" href="#prisma-indefinito" aria-label="Permalink to “Prisma indefinito”">​</a></h1><p>Consideriamo un poligono qualunque sul piano <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>α</mi></mrow><annotation encoding="application/x-tex">\\alpha</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span></span></span></span> e consideriamo un poligono congruente ad esso sul piano <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>β</mi></mrow><annotation encoding="application/x-tex">\\beta</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0528em;">β</span></span></span></span> diverso e parallelo ad <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>α</mi></mrow><annotation encoding="application/x-tex">\\alpha</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span></span></span></span>.</p><p>Consideriamo poi le congiungenti i punti corrispondenti dei perimetri dei due poligoni congruenti: in tal modo l&#39;insieme di tali rette definiscono una <strong>superficie prismatica indefinita</strong>.</p><p>Lo spazio viene diviso in due parti da tale superficie prismatica: una parte non limitata ed una parte limitata da parti di piano che sono le facce del prisma.</p><p>Se poi consideriamo tutte le rette congiungenti punti corrispondenti dei due poligoni congruenti (perimetro compreso), allora consideriamo la parte di spazio circondata dalla superficie prismatica ed otteniamo il cosiddetto <strong>prisma indefinito</strong>.</p><blockquote><p>Se partiamo da un poligono convesso possiamo definire come prisma la parte di spazio convessa delimitata dalla superficie prismatica chiusa (chiusa perché così comprende anche il bordo).</p></blockquote><p>Quindi abbiamo la definizione:</p><p>Si definisce <strong>prisma indefinito</strong> la parte di spazio delimitata da tutte le rette parallele fra loro e passanti per i punti corrispondenti di due poligoni congruenti disposti su piani paralleli (e diversi).</p>`,8)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};